function caret(base, v) {
  const [b, x] = [base, v].map((s) => s.split('.').map(Number));
  const lead = b.findIndex((n) => n !== 0);
  const i = lead === -1 ? 2 : lead;
  const sameUpTo = b.slice(0, i + 1).every((n, k) => n === x[k]);
  const notLower = x[0] - b[0] || x[1] - b[1] || x[2] - b[2];
  return sameUpTo && notLower >= 0;
}
